const body = ($input.first().json.body) || $input.first().json || {};
const tipo = (body.tipo_negocio || 'real estate agency').toString().trim() || 'real estate agency';
const ciudad = (body.ciudad || 'Miami, FL, USA').toString().trim() || 'Miami, FL, USA';
let max = parseInt(body.max, 10);
if (isNaN(max)) max = 20;
max = Math.min(50, Math.max(1, max));

// `google_web` sigue en la lista porque el CRM lo ofrece, pero su rama no
// guarda nada (ver nodo "Fuente No Disponible"). Antes ejecutaba el actor de
// Apify, pagaba los creditos y tiraba el resultado: eso ya no pasa.
const fuentesValidas = ['google_maps', 'google_web', 'linkedin', 'instagram', 'facebook'];
let fuente = (body.fuente || 'google_maps').toString().trim();
if (!fuentesValidas.includes(fuente)) fuente = 'google_maps';

return [{ json: {
  searchStringsArray: [tipo],
  locationQuery: ciudad,
  maxCrawledPlacesPerSearch: max,
  language: 'en',
  tipo_negocio: tipo,
  ciudad,
  fuente,
  consulta: `${tipo} / ${ciudad}`
} }];

// Un unico paquete con el lote COMPLETO. Es deliberado: si se enviara item a
// item, un fallo intermedio dejaria la mitad de los leads fuera y sin rastro
// (el sintoma "Apify dice 10 y el CRM guarda 1"). Asi entra el lote entero o
// falla el lote entero, y en ambos casos queda registrado en lead_imports.
const lote = $input.all().map(i => i.json);
const prep = $('Preparar Busqueda').first().json;

return [{ json: {
  p_lote: lote,
  p_fuente: prep.fuente || 'google_maps',
  p_consulta: prep.consulta
} }];

// El resultado del import es la prueba de si el lote llego completo. Se deja
// visible en la ejecucion para no tener que abrir la base de datos.
const r = $json;
console.log(`[captacion] recibidos=${r.recibidos} insertados=${r.insertados} actualizados=${r.actualizados} descartados=${r.descartados}`);
if (r.descartados > 0) console.log('[captacion] descartados:', JSON.stringify(r.detalle));
return [{ json: r }];
